import type { CharacterEntry, CharacterCollection, VisualAxes } from "@/types/visual.types";

// Visual Character Discovery — curated design-language database.
//
// Generated from a 375-character CSV export (all 32 Giantverse archetypes
// represented, minimum 10 characters each) — see this feature's commit for
// the source file. No copyrighted artwork is bundled: `image` is null and
// the UI renders a monogram instead. Every entry carries a copyright
// notice; the analyses are educational commentary on published character
// designs.
//
// `profile` values are hand-authored 0..1 positions on the same measurement
// axes the client-side embedding produces. They describe the DESIGN, so the
// matcher can say "you visually resemble this design language" — never
// "you are this character".

function axes(p: Partial<VisualAxes>): VisualAxes {
  return {
    faceLength: 0.5, jawSharpness: 0.5, eyeNarrowness: 0.5, browWeight: 0.5,
    hairDarkness: 0.5, hairVolume: 0.5, expressionNeutrality: 0.5, symmetry: 0.6,
    contrast: 0.5, angularity: 0.5, glasses: 0.0, warmth: 0.5,
    ...p,
  };
}

